async function 할일추가(text) {
  const 임시 = { id: crypto.randomUUID(), text, 보류: true };   // 클라가 id 를 만든다
  로컬에추가(임시);           // 화면은 즉시 반영
  큐에넣기({ type: 'add', ...임시 });

  try {
    const 결과 = await 서버로보내기(임시);
    로컬갱신(임시.id, { ...결과, 보류: false });
  } catch (e) {
    if (되돌릴수없는오류(e)) { 로컬에서제거(임시.id); 사용자에게알림('저장 실패'); }
    // 네트워크 오류면 큐에 남겨 두고 나중에 재시도
  }
}
